import sys
from array import array
from typing import List, Tuple, TypeVar, Generic, Sequence, Union

def input():
	return sys.stdin.buffer.readline().decode('utf-8')

def main():
	t = int(input())
	ans = ['-1'] * t
	for ti in range(t):
		n = int(input())
		a = [0] + list(map(int, input().split()))
		p = [0] * (n + 1)
		(lo, i) = (1, 1)
		ok = 1
		while i <= n:
			if a[i] == -1:
				p[i] = lo
				i += 1
				lo += 1
				continue
			stack = [[a[i], lo + a[i] - i, lo + (a[i] - i) - 1]]
			j = i
			while j < a[i]:
				if j == stack[-1][0]:
					lo = stack.pop()[1]
				if a[j] == -1 or a[j] == stack[-1][0]:
					pass
				elif a[j] > stack[-1][0]:
					ok = 0
					break
				else:
					stack.append([a[j], lo + a[j] - j, lo + (a[j] - j) - 1])
				p[j] = stack[-1][2]
				stack[-1][2] -= 1
				j += 1
			lo = stack.pop()[1]
			i = j
			if not ok:
				break
		else:
			ans[ti] = ' '.join(map(str, p[1:]))
	sys.stdout.buffer.write(('\n'.join(ans) + '\n').encode('utf-8'))
main()
